const tokenVecino = pm.collectionVariables.get("token_vecino");

if (!tokenVecino) {
    throw new Error("Falta token_vecino. Ejecuta primero Login vecino.");
}

pm.collectionVariables.unset("id_reclamo_cancelar");

pm.sendRequest({
    url: "http://localhost:3000/api/reclamos",
    method: "POST",
    header: {
        Authorization: `Bearer ${tokenVecino}`
    },
    body: {
        mode: "formdata",
        formdata: [
            {
                key: "id_categoria",
                value: "1",
                type: "text"
            },
            {
                key: "descripcion",
                value: "Reclamo temporal para prueba automatizada de cancelación",
                type: "text"
            },
            {
                key: "ubicacion",
                value: "Calle Los Aromos 100",
                type: "text"
            }
        ]
    }
}, function (error, response) {
    if (error) {
        throw new Error("Error al crear reclamo: " + error.message);
    }

    if (response.code !== 201) {
        throw new Error(
            "No se pudo crear el reclamo. HTTP " + response.code
        );
    }

    const datos = response.json();

    if (!datos.ok || !datos.reclamo?.id_reclamo) {
        throw new Error("La respuesta no contiene un ID de reclamo válido.");
    }

    pm.collectionVariables.set(
        "id_reclamo_cancelar",
        datos.reclamo.id_reclamo
    );
});

